/// 把一份编译好的导出计划写进 C++ 渲染器。
pub fn from_plan(plan: &Plan) -> Result<PlanBuilder, Error> {
    let mut builder = PlanBuilder::new()?;

    builder.set_meta(&Meta {
        project_root: &plan.meta.project_root,
        stage: (plan.meta.stage_w, plan.meta.stage_h),
        output: (plan.meta.output_w, plan.meta.output_h),
        fps: (plan.meta.fps_num, plan.meta.fps_den),
        duration_us: plan.meta.duration_us,
        ui: plan.meta.ui,
        font_scale: plan.meta.font_scale,
        disable_filters: plan.meta.disable_filters,
    })?;

    for (id, asset) in &plan.assets {
        builder.add_asset(id, &asset.path)?;
    }

    for key in &plan.background {
        builder.add_background(&BackgroundSpec {
            t_us: key.t_us,
            asset: key.asset.as_deref(),
            transform: transform(&key.transform),
            alpha: key.alpha,
            enter_ms: key.enter_ms,
            exit_ms: key.exit_ms,
            ease: &key.ease,
            snap_transform: key.snap_transform,
        })?;
    }

    for key in &plan.stage {
        builder.add_stage(&StageSpec {
            t_us: key.t_us,
            alpha: key.alpha,
            enter_ms: key.enter_ms,
            ease: &key.ease,
        })?;
    }

    for key in &plan.film {
        builder.add_film(&FilmSpec {
            t_us: key.t_us,
            enabled: key.enabled,
        })?;
    }

    for track in &plan.figures {
        builder.add_figure(&track.id, track.z_index)?;
        for key in &track.keys {
            builder.add_figure_key(
                &track.id,
                &FigureKeySpec {
                    t_us: key.t_us,
                    asset: key.asset.as_deref(),
                    live2d: key.live2d.as_deref(),
                    expression: key.expression.as_deref(),
                    motion: key.motion.as_deref(),
                    transform: transform(&key.transform),
                    alpha: key.alpha,
                    visible: key.visible,
                    enter_ms: key.enter_ms,
                    exit_ms: key.exit_ms,
                    figure_switch: key.figure_switch,
                    ease: &key.ease,
                    snap_transform: key.snap_transform,
                },
            )?;
        }
        for pose in &track.poses {
            let blink = Blink {
                interval_ms: pose.blink.interval_ms,
                interval_random_ms: pose.blink.interval_random_ms,
                closing_ms: pose.blink.closing_ms,
                closed_ms: pose.blink.closed_ms,
                opening_ms: pose.blink.opening_ms,
            };
            let focus = Focus {
                x: pose.focus.x,
                y: pose.focus.y,
                instant: pose.focus.instant,
            };
            builder.add_figure_pose(
                &track.id,
                pose.t_us,
                pose.motion_start_us,
                pose.expression_start_us,
                pose.motion.as_deref(),
                pose.expression.as_deref(),
                &blink,
                &focus,
            )?;
        }
    }

    for segment in &plan.texts {
        builder.add_text(&TextSpec {
            start_us: segment.start_us,
            end_us: segment.end_us,
            speaker: &segment.speaker,
            font_size: &segment.font_size,
            reveal_ms_per_char: segment.reveal_ms_per_char,
            fade_ms: segment.fade_ms,
            figure: segment.figure.as_deref(),
        })?;
        for (index, line) in segment.lines.iter().enumerate() {
            if index > 0 {
                builder.add_text_line()?;
            }
            for TextChar { text, .. } in &line.chars {
                builder.add_text_char(text)?;
            }
        }
    }

    for segment in &plan.choices {
        builder.add_choice(segment.start_us, segment.end_us, segment.selected)?;
        for option in &segment.options {
            builder.add_choice_option(&option.prompt, option.target.as_deref())?;
        }
    }

    for segment in &plan.intros {
        builder.add_intro(
            segment.start_us,
            segment.end_us,
            &segment.font_size,
            &segment.animation,
        )?;
        for line in &segment.lines {
            builder.add_intro_line(line)?;
        }
    }

    for segment in &plan.videos {
        builder.add_video(&VideoSpec {
            start_us: segment.start_us,
            end_us: segment.end_us,
            path: &segment.path,
        })?;
    }

    for event in &plan.audio {
        builder.add_audio(&AudioSpec {
            start_us: event.start_us,
            end_us: event.end_us,
            path: &event.path,
            kind: match event.kind {
                PlanAudioKind::Bgm => AudioKind::Bgm,
                PlanAudioKind::Vocal => AudioKind::Vocal,
                PlanAudioKind::Effect => AudioKind::Effect,
                PlanAudioKind::Video => AudioKind::Video,
            },
            volume: event.volume,
            loop_: event.loop_,
            fade_in_ms: event.fade_in_ms,
            fade_out_ms: event.fade_out_ms,
        })?;
    }

    Ok(builder)
}

